  const sevRowsInput = (lim, disabled, dir, unit) => SEVS.slice().reverse().map((k) => `<div class="limitrow"><span class="sev ${k}">${SEV_LABEL[k]}</span><input type="number" step="any" data-lim="${k}" value="${lim[k] ?? ''}" placeholder="—" ${disabled ? 'disabled' : ''}><span class="sk">${k === 'emergency' ? 'phone call and hooter · everyone' : k === 'major' ? 'full-screen alarm · Leads told' : k === 'minor' ? 'WhatsApp to Operators' : 'in the app only'}</span></div>`).join('');

