      segWire(el, 'aDir', (v) => { a.direction = v; draw(); });
      $$('[data-lim]', el).forEach((i) => i.onchange = () => { const v = i.value === '' ? null : +i.value; if (a.limits === 'custom') a.custom[i.dataset.lim] = v; draw(); });
      $('[data-custom]', el)?.addEventListener('click', (e) => { e.preventDefault(); a.limits = 'custom'; a.custom = { ...(s.limits || { caution: null, minor: null, major: null, emergency: null }) }; a.direction = s.direction || 'below'; draw(); });
      $('[data-usesensor]', el)?.addEventListener('click', (e) => { e.preventDefault(); a.limits = 'sensor'; draw(); });
