      $('#aHold', el) && ($('#aHold', el).onchange = (e) => { a.holdMin = +e.target.value; draw(); });
      $('#aCycle', el) && ($('#aCycle', el).onchange = (e) => { a.cycle = e.target.value ? { id: d.cycles.find((c) => c.eq === sensorHome(s).id).id, only: e.target.value } : null; });
      segWire(el, 'aClose', (v) => { a.closes.mode = v; draw(); });
