      $('.sb', el).classList.add('narrow'); railWire(el, go); stepFoot(el, step, 3, { go });
      $('[data-cancel]', el)?.addEventListener('click', closeSheet);
      $('#wSensor', el) && ($('#wSensor', el).onchange = (e) => { w.sensor = e.target.value; w.name = ''; draw(); });
      $('#wFlow', el) && ($('#wFlow', el).onchange = (e) => { w.flow = e.target.value || null; w.name = ''; draw(); });
      $('#wName', el) && ($('#wName', el).oninput = (e) => { w.name = e.target.value; });
      $('#wDo', el) && ($('#wDo', el).onchange = (e) => { w.doWhen = e.target.value === '' ? null : +e.target.value; draw(); });
