        <div class="inl" style="margin-bottom:14px"><span class="mono" style="font-size:22px">${s.kind === 'status' ? (s.reading ? 'ON' : 'OFF') : s.reading} ${esc(s.unit)}</span>${s.state === 'stale' ? '<span class="chip warn">Not reporting · last sample 47 min ago</span>' : s.state === 'not_trusted' ? '<span class="chip err">Not trusted · alerts paused</span>' : '<span class="chip ok">Live</span>'}${s.setpoint ? `<span class="chip">PLC set point ${s.setpoint.value} ${esc(s.unit)}</span>` : ''}</div>
