      const body = `<div id="failSlot"></div><div class="f inline"><div><label class="l">Name</label><input type="text" id="fName" value="${esc(f.name)}" ${ro ? 'disabled' : ''} placeholder="${f.kind === 'diagnostic' ? 'Low DO diagnostic' : 'Backwash filter'}"></div><div><label class="l">For which machine type</label><select id="fFor" ${ro ? 'disabled' : ''}><option value="">Any</option>${[...new Set(d.equipment.map((e) => e.type))].map((t) => `<option ${f.forType === t ? 'selected' : ''}>${esc(t)}</option>`).join('')}</select></div></div>
        <div class="q" style="font-size:15px">Steps <span class="muted small" style="font-weight:400">${f.steps.length} of 20</span></div><div class="steps">${f.steps.map(stepRow).join('') || `<div class="empty2"><b>No steps yet</b><p>${f.kind === 'diagnostic' ? 'Start with the first question an experienced operator would ask.' : 'Start with the first thing the operator does, in their words.'}</p></div>`}</div>
        ${ro ? '' : `<div class="actions" style="margin-top:10px"><button class="btn sm" data-add="instruction">+ Instruction</button><button class="btn sm" data-add="question">+ Question</button><button class="btn sm" data-add="reading">+ Reading</button><button class="btn sm" data-add="wait">+ Wait</button></div>`}
        <details class="adv" ${open || noTag || !runs.length ? 'open' : ''}><summary>Ready to publish?</summary><div class="checks">${f.steps.length ? '' : '<div class="c err">✕ <span>Needs at least one step.</span></div>'}${open ? `<div class="c warn">! <span>${plural(open, 'answer')} not decided yet. Honest work in progress; blocks publish.</span></div>` : ''}${noTag ? `<div class="c err">✕ <span>${plural(noTag, 'reading step')} not bound to a tag.</span></div>` : ''}${f.kind === 'diagnostic' ? f.steps.flatMap((st) => Object.values(st.answers || {})).filter((a) => a.t === 'cause' && !cause(a.id).fix && !cause(a.id).sensorFault).map((a) => `<div class="c warn">! <span>${esc(cause(a.id).name)} has no action flow yet.</span></div>`).join('') : ''}${runs.length ? `<div class="c ok">✓ <span>Runs from: ${runs.map(esc).join(' · ')}</span></div>` : '<div class="c warn">! <span>Nothing runs this flow yet. Attach it from an alert, a schedule or a cause.</span></div>'}</div></details>
        <div class="model" style="margin-top:12px"><div class="fs" style="font-family:var(--mono);font-size:11px">Procedure { treeType:'${f.kind === 'diagnostic' ? 'branching' : 'linear'}', steps:[{ stepType, responseType, answers:{ YES|NO|ABOVE|BELOW → step|cause } }] }</div></div>`;
      const foot = ro ? `<button class="btn" data-cancel>Close</button>` : `<span class="grow">Draft saves skip every check.</span>${!isNew ? '<button class="btn ghost danger" data-archive>Archive</button>' : ''}<button class="btn" data-cancel>Cancel</button><button class="btn" data-draft>Save draft</button><button class="btn primary" data-publish ${(!f.steps.length || open || noTag || !f.name.trim()) ? 'disabled' : ''}>Publish v${f.status === 'published' ? f.version + 1 : f.version}</button>`;
