      $('#fFor', el).onchange = (e) => { f.forType = e.target.value || null; };
      $$('[data-add]', el).forEach((b) => b.onclick = () => stepDialog({ id: (f.steps.at(-1)?.id || 0) + 1, type: b.dataset.add, text: '', answers: f.kind === 'diagnostic' && (b.dataset.add === 'question' || b.dataset.add === 'reading') ? (b.dataset.add === 'question' ? { Yes: { t: 'open' }, No: { t: 'open' } } : { Above: { t: 'open' }, Below: { t: 'open' } }) : undefined }, (st) => { f.steps.push(st); draw(); }));
